'ob.texts_title' => 'Offer texts',
'ob.texts_lede' => 'The text blocks of the offer document — introduction, scope, exclusions, validity, prices and payment, terms, closing — per layout, language, branch and customer. Copied into each new offer, where they can still be edited.',
'ob.texts_none' => 'No template yet — the built-in texts apply. Add one with the buttons on the right.',
'ob.block' => 'Block',
'ob.texts_resolve' => 'Which template applies: the most specific active one — customer, then branch, then language, then layout; a template bound to another customer, branch, language or layout is never used. The language is the one of the customer\'s portal accounts.',
'ob.text_name_ph' => 'e.g. Terms — Italian branch',
'ob.any_layout' => '— any layout —',
'ob.builtin_of' => 'Built-in text',
'ob.texts_order' => 'Order in the document: Introduction · Scope · Prices (table) · Exclusions · Validity · Prices and payment · Terms and conditions · Closing. An empty block is not printed.',
'ob.d_intro' => "Dear Sirs,\n\nThank you for your enquiry. Further to our discussion we are pleased to submit our offer {no} for {vessel}, as detailed below.",
'ob.d_scope' => 'The offer covers the services and supplies listed in the price table. Work is carried out by qualified Golden A/S engineers according to the manufacturers\' instructions, the applicable class and flag requirements and the General Conditions of Service of Golden A/S.',
'ob.d_scope_system' => 'The offer covers the engineering, supply, installation supervision, commissioning and documentation of the system described in the price table, according to the manufacturers\' instructions, the applicable class and flag requirements and the General Conditions of Service of Golden A/S.',
'ob.d_scope_remote' => 'The offer covers the remote support services, equipment and plans listed in the price table under the Remote Support & AR — OceanOpulence™ programme, according to the General Conditions of Service of Golden A/S.',
'ob.d_exclusions' => 'Unless stated in the price table, the following are not included: spare parts and materials; travel, accommodation and daily allowances (charged as per the Golden A/S service rates); class, flag and port fees; work outside normal working hours; delays beyond the control of Golden A/S.',
'ob.d_validity' => 'This offer is valid for {validity_days} days, until {valid_until}.',
'ob.d_payment' => 'Prices are in {currency}, exclusive of VAT where applicable. Hourly services are invoiced on the actual hours worked per the attached rates, with the minimum charges of the rate card; fixed prices as stated. Payment by bank transfer or credit card according to our General Conditions of Service.',
'ob.d_terms' => 'Overtime daily and hourly rates apply on Saturdays, Sundays, holidays, and in excess of eight (8) hours Monday to Friday in Greece or ten (10) hours abroad and on the Greek islands. Travelling time, fixed daily allowance, kilometre charges and travel costs apply as per the Golden A/S service rates {rate_list}. A public fee of 180.00 € applies for the work permit issuance in Greek designated repair zones.',
'ob.d_closing' => "We trust the above meets your requirements and remain at your disposal for any clarification.\n\nBest regards,\n{user}\n{branch}",
