'hra.welcome_title' => 'Hello {n}',
'hra.welcome_1' => 'This assistant collects the data of your employee card in six short steps. Every field is pre-filled with what HR holds today: confirm it, correct it, or leave it. You can stop at any time and continue later — also from your phone.',
'hra.privacy_title' => 'How your data is handled',
'hra.privacy_1' => 'Controller: Golden Automation Systems (Sistimata Ischyos ATEE), Kiou 5, Keratsini — for the Italian branch GOLDEN AS ITALIAN. Purpose: keeping the personnel record required by employment, social-security and tax law, and contacting you or your emergency contact. Legal basis: the employment contract and the legal obligations of the employer.',
'hra.privacy_2' => 'What you enter here is kept in a staging area until HR approves it; your identification numbers (AMKA, VAT, ID, passport, IBAN) are encrypted there and readable by HR only. Recipients: HR, the Owner and, for payroll, the company accountant. Retention: the staging data is deleted 90 days after the decision; the card itself follows the retention of the personnel file.',
'hra.privacy_3' => 'Your rights: access, rectification (through this assistant), erasure and restriction where the law allows, and a complaint to the Hellenic Data Protection Authority (dpa.gr). Questions: HR › Messages with HR.',
'hra.consent_label' => 'I have read the notice above and I want to continue.',
