'hra.assist_p_text' => 'Extract the employee record fields below from the text the employee wrote about himself. Use exactly the field formats: dates as YYYY-MM-DD, Greek AMKA 11 digits, Greek VAT (ΑΦΜ) 9 digits, IBAN without spaces, gender m or f, marital one of single / married / divorced / widowed / partnership, children as a number, children_years as years separated by commas.',
'hra.assist_p_doc' => 'Read the identity document in the picture (ID card or passport) and extract the employee record fields below. Use exactly the field formats: dates as YYYY-MM-DD, document numbers as printed, names in the Greek alphabet for name_el when the document is Greek.',
