'et.d_s_rfq' => "Request for quotation {no} — {branch}",
'et.d_b_rfq' => "Dear Sir / Madam,\n\nPlease find attached {doc}. Kindly quote your best price, delivery time, validity and payment terms per line, stating the maker, type and country of origin, and return your offer by the date indicated on the document, quoting our number.\n\nBest regards,\n{user}\n{branch}",
'et.d_s_po_chase' => "Purchase order {no} — delivery status",
'et.d_b_po_chase' => "Dear Sir / Madam,\n\nWith reference to {doc}, we kindly ask you to confirm the current status of our order: the goods ready for dispatch, the shipping date, the forwarder and the tracking reference, as well as any item still outstanding and its expected date.\n\nThe delivery is linked to a vessel schedule; please inform us of any delay at once.\n\nBest regards,\n{user}\n{branch}",
'et.d_s_ncr' => "Non-conformance on purchase order {no}",
'et.d_b_ncr' => "Dear Sir / Madam,\n\nOn receipt of the goods of {doc} we recorded the non-conformances described in the attached report (quantity, damage or deviation from the order). Kindly confirm within three working days how you intend to settle them — replacement, credit note or repair — together with the date.\n\nThe non-conforming items are held at our warehouse at your disposal.\n\nBest regards,\n{user}\n{branch}",
'et.d_s_remittance' => "Payment advice — {branch}",
'et.d_b_remittance' => "Dear Sir / Madam,\n\nPlease find attached our payment advice for {doc}. The amount has been transferred to the bank account stated on your invoice; kindly allocate it to the invoices listed and send us the receipt.\n\nBest regards,\n{user}\n{branch}",
'em.template' => "Template",
