'et.d_s_rc_general' => "Your application {no} — {title} — Golden A/S",
'et.d_s_rc_shortlisted' => "Your application for {title} — next step — Golden A/S",
'et.d_s_rc_interview' => "Interview invitation — {title} — Golden A/S",
