'et.d_s_rc_rejected' => "Your application for {title} — Golden A/S",
'et.d_b_rc_general' => "Dear {name},\n\nThank you for your application {no} for the position of {title} ({doc}).\n\n\n\nBest regards,\n{user}\n{branch}",
'et.d_b_rc_shortlisted' => "Dear {name},\n\nThank you for your application for the position of {title}. We have reviewed it with interest and would like to invite you to the next step of our selection process.\n\nWe will contact you shortly to arrange a convenient time. In the meantime, please let us know if anything in your availability changes.\n\nBest regards,\n{user}\n{branch}",
'et.d_b_rc_interview' => "Dear {name},\n\nFollowing your application for the position of {title}, we would like to invite you to an interview.\n\nDate and time: \nDuration: \nFormat / location: \nInterviewers: \n\nPlease confirm by return that the proposed time suits you, or propose an alternative.\n\nBest regards,\n{user}\n{branch}",
'et.d_b_rc_offer' => "Dear {name},\n\nWe are pleased to inform you that, following the selection process for the position of {title}, we would like to offer you the role.\n\nThe formal offer with the terms of employment is attached / will follow separately. Please review it and let us know your decision by .\n\nWe look forward to welcoming you to the team.\n\nBest regards,\n{user}\n{branch}",
'et.d_b_rc_rejected' => "Dear {name},\n\nThank you for your application for the position of {title} and for the time you invested in our selection process.\n\nAfter careful consideration we have decided to proceed with other candidates whose profile is closer to the requirements of this role. We will keep your details on file for six months and will contact you if a suitable position opens.\n\nWe wish you every success.\n\nBest regards,\n{user}\n{branch}",
'rc.key_once_hint' => 'Copy it now into the website repository secret PORTAL_RC_KEY (or PORTAL_STATS_KEY) — on the next page load it is masked again.',
// R91-003 outgoing mail
'web.mail' => 'Outgoing e-mail',
'web.mail_smtp' => 'Authenticated SMTP via {host} as {user} — candidate, HR and website messages pass SPF/DMARC.',
'web.mail_phpmail' => 'PHP mail() — not configured for SMTP. goldenas.com.gr mail is on Microsoft 365 and its SPF rejects other senders: messages will land in junk.',
'web.mail_hint' => 'Preferred: Microsoft Graph with OAuth2 client credentials — set the graph block in customer/app/config.php (tenant, client_id, client_secret, from) from an Entra app registration with the application permission Mail.Send, limited to the sending mailbox by an application access policy; no mailbox password is stored. Fallback: the smtp block (smtp.office365.com:587, mailbox with "Authenticated SMTP" and an app password). The website uses the same values in its api/config.php.',
